head.script:
scwin.onpageload = function() {

};

/**
 * @method
 * @name get
 * @description get
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.get = function (id) {
	return $p.getComponentById(id)
};

/**
 * @method
 * @name create
 * @description create
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.create = async function (opt = {}) {
	opt.id = opt.id || opt.type+"_"+Math.floor(Math.random()*10000);
    opt.attr = opt.attr || {};
    opt.parent = opt.parent || $c.comp.get("mf_wq_uuid_3");
    opt.itemSet = opt.itemSet || {};
    opt.css = opt.css || {};
    opt.classes = opt.classes || [];
    var tag = opt.type;
    if(opt.type == "trigger"){

    }else if(opt.type == "emoji"){
        tag = "trigger";
    }else if(opt.type == "list"){
        tag = "group";
        opt.attr.dynamic = true;
    }else if(opt.type == "form"){
        tag = "group";
    }else if(opt.type == "thead"){
        tag = "group";
    }else if(opt.type == "tbody"){
        tag = "group";
    }else if(opt.type == "tr"){
        tag = "group";
    }else if(opt.type == "th"){
        tag = "group";
    }else if(opt.type == "td"){
        tag = "group";
    }
    if ($p.getComponentById(opt.id)) {
        throw new Error("[comp.create] 이미 존재하는 ID: " + opt.id);
    }
    await $p.dynamicCreate(opt.id, tag, opt.attr, opt.parent, opt.itemSet);
    const comp = $p.getComponentById(opt.id);
    const el = comp.render;
    if(opt.type == "trigger"){
        comp.setValue(opt.text);
        opt.css = {
            ...{width : "80px", height : "24px"},
            ...opt.css,
        };
    }else if(opt.type == "emoji"){
        comp.setValue(opt.text);
        opt.css = {
            ...{
                width : "20px",
                height : "20px",
                float : "right",
                fontFamily : "Segoe UI Emoji",
                backgroundColor : "transparent",
                border : "0px",
            },
            ...opt.css,
        };
    }else if(opt.type == "input"){
        opt.css = {
            ...{textAlign : "left"},
            ...opt.css,
        };
    }else if(opt.type == "selectbox"){
        opt.css = {
            ...{width : "100px", height : "24px"},
            ...opt.css,
        };
        const interval = setInterval(function(){
            if($p.getComponentById(comp.id+"_itemTable")){
                $p.getComponentById(comp.id+"_itemTable").setStyle({zIndex : 10000});
                clearInterval(interval);
            }
        }, 500);
    }else if(opt.type == "group"){
        comp.render.append(opt.text||"");
    }else if(opt.type == "list"){
        opt.classes.push("tbl_comn");
    }else if(opt.type == "form"){
        opt.css.width = "200px";
        opt.classes.push("tbl_comn");
    }else if(opt.type == "tr"){
        opt.classes.push("col_group");
    }
    comp.setAttribute(opt.attr);
    comp.setStyle({...{}, ...opt.css});
    if(opt.click){
        comp.bind("click", opt.click);
    }
    if(opt.change){
        comp.bind("change", opt.change);
    }
    opt.classes.forEach(function(data){
        comp.addClass(data);
    });
    if(opt.callback){
        opt.callback({
            comp : comp,
            el : comp.render,
        });
    }
    comp._ = {};
    comp._.opt = opt;
    comp._.data = opt.data;
    comp._.opener = opt.opener;
    comp._.target = opt.target;
    comp._.funs = opt.funs;
    return comp;
};

/**
 * @method
 * @name createPopup
 * @description createPopup
 * @param {object} opt option
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example
 */
scwin.createPopup = async function (opt = {}) {
	const popup = await $c.comp.create({
        id : opt.id,
        classes : ["__popup"],
        type : "group",
        css : {
            minWidth : "200px",
			minHeight : "200px",
			position : "absolute",
			bottom : "0px",
			right : "0px",
			backgroundColor : "#ffe8a3",
        },
    });
    popup._.header = await $c.comp.create({
        parent : popup,
        id : popup.id + "_header",
        type : "group",
        css : {
            width : "100%",
			height : "20px",
        },
    });
    popup._.body = await $c.comp.create({
        parent : popup,
        id : popup.id + "_body",
        type : "group",
        css : {
            width : "100%",
			height : "100%",
        },
    });
    await opt.draw({
        popup : popup,
        header : popup._.header,
        body : popup._.body,
    });
    return popup;
};
